namespace sv_4060cfefc02f41819ee9214ba3cd43ec.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<CascadingValue Value="currentSize" Name="ScreenSize">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    private ScreenSize currentSize = ScreenSize.Desktop;
    private IJSObjectReference? module;
    private DotNetObjectReference<ScreenSizeProvider>? objRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            objRef = DotNetObjectReference.Create(this);
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-4060cfefc02f41819ee9214ba3cd43ec/js/screenSizeInterop.js");
            await module.InvokeVoidAsync("initialize", objRef);
        }
    }

    [JSInvokable]
    public void OnViewportWidthChanged(int width)
    {
        var newSize = width switch
        {
            < 768 => ScreenSize.Mobile,
            < 1024 => ScreenSize.Tablet,
            _ => ScreenSize.Desktop
        };

        if (newSize != currentSize)
        {
            currentSize = newSize;
            StateHasChanged();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("dispose");
            await module.DisposeAsync();
        }
        objRef?.Dispose();
    }
}

let dotNetRef = null;
let resizeHandler = null;

export function initialize(objRef) {
    dotNetRef = objRef;

    resizeHandler = () => {
        dotNetRef.invokeMethodAsync('OnViewportWidthChanged', window.innerWidth);
    };

    window.addEventListener('resize', resizeHandler);

    // Send initial width immediately
    dotNetRef.invokeMethodAsync('OnViewportWidthChanged', window.innerWidth);
}

export function dispose() {
    if (resizeHandler) {
        window.removeEventListener('resize', resizeHandler);
        resizeHandler = null;
    }
    dotNetRef = null;
}

